const pageSlotPredicate = `
	FROM page_components pc
	JOIN pages p ON p.id = pc.page_id
	WHERE p.site_id = $1
	  AND ($2 = '' OR p.name = $2)`

var PageSlotIdentitiesSQL = `
	SELECT COALESCE(pc.slot_name, ''), COALESCE(pc.component_id::text, '')` + pageSlotPredicate + `
	ORDER BY pc.position ASC`

func SlotNameSet(rows []PageSlotRow) map[string]map[string]bool {
	out := make(map[string]map[string]bool)
	for _, r := range rows {
		if r.Slot == "" { continue }
		if out[r.PageName] == nil { out[r.PageName] = make(map[string]bool) }
		out[r.PageName][r.Slot] = true   // NO conflict rule here, deliberately
	}
	return out
}

func loadPageSlotComponentIDs(ctx context.Context, db *sql.DB, siteID uuid.UUID, pageName string, logger *zap.Logger) (map[string]string, error) {
	rows, err := datahelpers.LoadPageSlotRows(ctx, db, siteID, pageName)
	if err != nil { return nil, err }
	return datahelpers.SlotIDMap(rows, "plan_sections", pageName, logger), nil
}

func (r *storedSlotRescue) verdict(ctx context.Context, pageName, sectionName string) slotVerdict {
	if r == nil || pageName == "" || sectionName == "" { return slotNotStored }
	if !r.loaded { r.load(ctx) }
	if r.failed { return slotUnknown }
	if r.set[pageName][sectionName] {   // PAGE-scoped: this is the property, not the comment
		r.kept++
		r.keptPages[pageName] = append(r.keptPages[pageName], sectionName)
		return slotStored
	}
	return slotNotStored
}

