func TestSlotNameSet_DoesNotInheritTheIDMapsConflictRule(t *testing.T) {
	rows := []PageSlotRow{
		{PageName: "index", Slot: "prose-0", ComponentID: "aaa"},
		{PageName: "index", Slot: "prose-0", ComponentID: "bbb"},   // disagreeing repeat
	}
	if ids := SlotIDMap(rows, "test", "index", zap.NewNop()); len(ids) != 0 {
		t.Fatalf("precondition: SlotIDMap should refuse the ambiguous slot")
	}
	if !SlotNameSet(rows)["index"]["prose-0"] {
		t.Fatalf("membership must still be true for a slot the page demonstrably carries; " +
			"inheriting the id map's conflict rule here would delete a real section")
	}
}

func TestStoredSlotRescue_IssuesNoQueryWhenEveryNameResolves(t *testing.T) {
	expectResolverQueries(mock)   // and deliberately NO page_components expectation
	params := validateSlotParams(siteID.String(), []interface{}{"hero", "faq"})
	if _, err := ValidateSitePlanAction(context.Background(), params); err != nil { t.Fatal(err) }
	if err := mock.ExpectationsWereMet(); err != nil {
		t.Errorf("unmet/unexpected expectations: %v", err)   // an eager load fails here
	}
}
